# gen-guides.ps1 — full travel guides. Pure ASCII.
. "$PSScriptRoot/gen-common.ps1"
function New-Guide($slug,$title,$desc,$lead,$sections,$fu,$related){
  $faqs=$fu+(Faq-Pick ($slug.Length*5) (9-$fu.Count))
  $body=Crumb @('<a href="/">Home</a>','<a href="/travel-guide/">Travel Guide</a>',$title)
  $body+="<section class=`"block`"><div class=`"wrap`" style=`"max-width:840px`"><p class=`"eyebrow`">Travel guide</p><h1>$title</h1><p class=`"lead`">$lead</p>$sections"
  $body+=(Faq-List $faqs)+"<h2>More planning answers</h2><p>$related</p>"
  $body+=(CTA-Band "Plan with a specialist" "Real answers for your dates and budget." $title)+"</div></section></main>"
  $canon="https://www.adventuresafariafrica.com/travel-guide/$slug/"
  $html=Shell $title $desc $canon $body ('<script type="application/ld+json">{"@context":"https://schema.org","@type":"Article","headline":"'+$title+'"}</script>'+(Faq-Schema $faqs))
  $html | Out-File -FilePath "travel-guide/$slug.html" -Encoding utf8
  "guide: $slug"
}
$REL='<a href="/travel-guide/african-safari-cost/">Cost</a> | <a href="/travel-guide/best-time-for-african-safari/">Best time</a> | <a href="/travel-guide/what-to-pack-for-safari/">Packing</a> | <a href="/travel-guide/safari-safety/">Safety</a> | <a href="/travel-guide/">All guides</a>'
New-Guide "safari-tipping" "Safari Tipping Guide: Who, How Much, by Country" "Safari tipping rates: guides, camps, porters, restaurants - dollars, euros or local currency." "Tipping rewards extraordinary service, never subsidizes wages on our trips - crews are paid properly first. Use these baselines, adjust for exceptional guiding." "<h2>Guides</h2><p>Driver-guides: 15 to 25 dollars per day per group (not per person), handed directly at farewell. Tracker teams in Sabi Sand and walking guides: 10 to 15 dollars per day split by the group.</p><h2>Camps and lodges</h2><p>Most camps run a communal tip box: 10 to 15 dollars per person per day covers housekeeping, waiters and back-of-house. Hand anything extra to individuals directly.</p><h2>Treks and extras</h2><p>Gorilla and Kilimanjaro porters: 20 to 30 dollars each - they carry your pack and steady you on slopes. Restaurants: 10 percent where service is not included. Balloon crews: 10 to 20 dollars per person.</p><h2>Currency</h2><p>US dollars (post-2009 notes, unmarked), euros, or local currency - small bills. ATMs in Arusha, Nairobi and Entebbe dispense local cash; lodges rarely break large notes.</p>" @(@{"q"="Is tipping expected or optional?";"a"="Genuinely optional and always appreciated - never a levy. Tip for knowledge, positioning and care, not out of obligation."},@{"q"="Should we tip in dollars or local currency?";"a"="Either. Dollars and euros spend easily in safari towns; local currency suits village purchases. Bring small denominations either way."},@{"q"="How do we tip Kilimanjaro crews fairly?";"a"="KPAP-standard operators pool tips transparently: roughly 250 to 350 dollars per climber for a 7-day route, distributed by role. Ask your operator for their schedule in writing."}) $REL
New-Guide "safari-visas" "Visas, Vaccinations and Health Prep for Safari" "Safari visas and health prep: eTA, e-visa, yellow fever rules, malaria prophylaxis notes." "Start paperwork 8 weeks out: passports need 6-plus months validity and blank pages, visas vary by arrival method, and your doctor - not forums - decides prophylaxis." "<h2>Visas by country</h2><p>Tanzania: visa on arrival for many nationalities (50 dollars, US citizens 100). Kenya: eTA online before travel. Uganda and Rwanda: e-visas applied in advance. Multi-country loops need each visa - East Africa tourist visa covers Kenya, Uganda and Rwanda on one sticker where eligible.</p><h2>Vaccinations</h2><p>Yellow fever certificate required when arriving from endemic countries (including transiting them over 12 hours). Routine boosters - tetanus, hepatitis A/B, typhoid - should be current. Requirements change: verify with a travel clinic 8 weeks before departure.</p><h2>Malaria and water</h2><p>Prophylaxis recommended across most safari regions except high-altitude and southern winter zones - take medical advice, take the tablets properly, and use repellent plus treated nets in the evening. Drink reputable bottled or treated water only.</p>" @(@{"q"="How long do e-visas and eTAs take?";"a"="Kenya eTA typically 72 hours; Uganda e-visa 3 to 5 working days. Apply at least two weeks out and carry printed confirmations."},@{"q"="Do children need full visas?";"a"="Yes - same requirements as adults, plus some countries ask for birth certificates or consent letters for minors traveling with one parent. Check per country."},@{"q"="What if we transit an endemic country?";"a"="Transits over 12 hours (including overnight connections) can trigger yellow fever certificate checks on arrival. Carry the booklet regardless."}) $REL
New-Guide "family-safari-guide" "Family Safari Guide: Ages, Parks and Pacing" "Family safari planning: minimum ages, malaria-free parks, pacing, rooms, teen trekking rules." "Kids remember safaris forever if pacing respects them: pools at every stop, walking and boating breaks between drives, private vehicles for nap-and-snack flexibility." "<h2>Ages that work</h2><p>Six plus suits East Africa fly-drive circuits; four plus works in malaria-free South African reserves. Gorilla trekking is strictly 15-plus; walking safaris usually 16-plus; balloon flights usually 7-plus.</p><h2>Malaria-free options</h2><p>Madikwe, Pilanesberg and Eastern Cape reserves offer Big Five without prophylaxis debates. Elsewhere, pediatric prophylaxis per your doctor plus nets and repellent manage risk well.</p><h2>Pacing and rooms</h2><p>Private vehicle always. Two-night stays minimum per stop. Family tents and interconnecting rooms at most lodges - request early, inventory is limited. Naivasha boats, Crescent Island walks and cultural mornings break up drive days beautifully.</p>" @(@{"q"="What age is best for a first safari?";"a"="Six to eight for East Africa; four-plus for malaria-free South Africa. Under-fours face lodge restrictions and long-drive limits."},@{"q"="Can teens trek gorillas?";"a"="At fifteen and above, yes - a superb older-teen milestone. Under-15s get chimps, savanna and forest walks instead."},@{"q"="How do we handle malaria with kids?";"a"="Pediatric formulations exist for most prophylaxis regimes; combine with nets, long sleeves and evening repellent. Malaria-free reserves remove the question entirely."}) $REL
New-Guide "first-safari" "First Safari? Start Here - Country, Days, Style" "First-safari playbook: picking a country, duration and style without expensive mistakes." "First safaris go wrong in predictable ways: too many parks, wrong month, shared vehicles with timetable tyranny. This playbook avoids all three." "<h2>Pick one country</h2><p>Tanzania or Kenya for classic game viewing; South Africa for easy family logistics; Uganda for primates. One country done well beats two rushed every time.</p><h2>Pick five to seven days</h2><p>Five days covers a classic circuit; seven adds Migration depth or a second ecosystem. Shorter only works as a fly-in express to one park.</p><h2>Go private, go dry season</h2><p>Your own vehicle removes every compromise that ruins first trips. Travel June to October or January to February for the easiest wildlife viewing.</p>" @(@{"q"="Tanzania or Kenya for a first safari?";"a"="Tanzania for the complete circuit plus Zanzibar; Kenya for easier logistics and slightly lower cost. Both deliver lions, elephants and the Migration in season."},@{"q"="What is the biggest first-timer mistake?";"a"="Overstuffing: four parks in five days means windscreens, not wildlife. Two to three parks with two-night stays wins."},@{"q"="Should first-timers add Zanzibar or trekking?";"a"="Beach after safari, always - three-plus nights. Save Kilimanjaro and gorillas for trip two unless fitness and budget are solid."}) $REL
New-Guide "photography" "Safari Photography: Lenses, Settings and Field Craft" "Safari photography guide: lenses, settings, beanbags, hides, dust and light." "Safari rewards preparation more than gear: positioning for light, patience at one sighting, and settings dialed before the leopard looks up." "<h2>Lenses</h2><p>A 100 to 400mm zoom covers 90 percent of sightings. Add a wide second body for herds, landscapes and camp life. Teleconverters help in open country, hinder in forest.</p><h2>Settings and field craft</h2><p>Shoot aperture-priority wide open at dawn and dusk; shutter priority 1/1000-plus for action; Auto ISO with a sane cap. Beanbags on the roof hatch beat tripods; turn off vehicle engines for vibration; anticipate - pre-focus where the animal is heading.</p><h2>Hides, dust and power</h2><p>Water-level hides at Mashatu and Kwara put lenses at eye level - book months ahead. Seal gear in dust bags between drives, carry a blower and sensor kit, and confirm vehicle charging (ask for inverters on camping trips).</p>" @(@{"q"="What is the one-lens safari kit?";"a"="A 100-400mm zoom on a crop or full-frame body, plus a phone for landscapes. Add a 1.4x converter for open-country trips."},@{"q"="How do we handle dust?";"a"="Never change lenses outside the vehicle; bag bodies between sightings; blow (never wipe) sensors daily. Green-season dust is milder."},@{"q"="Is a second body worth it?";"a"="Yes - a wide body avoids missed herd-and-sky moments while the long lens stays mounted. Even an older body earns its weight."}) $REL
New-Guide "solo-safari" "Solo Safari Guide: Supplements, Safety and Routes" "Solo safari planning: single supplements, safety, social group options and best routes." "Solo safaris are superb and common: private vehicles maximize sightings per hour, groups maximize company per dollar, and supplements are negotiable math, not mystery." "<h2>Single supplements</h2><p>Expect 20 to 50 percent over per-person sharing rates where lodges charge per room; vehicles cost the same for one or six. Four-plus traveler math never applies - ask for the honest per-trip supplement.</p><h2>Safety and social life</h2><p>Guided safaris are among the safest solo travel in Africa: door-to-door transfers, camp staff who notice everything, communal fire dinners. Join-in groups add instant company; private trips add total freedom.</p><h2>Best solo routes</h2><p>Tanzania and Kenya classics for first solos; Uganda for primate people; Namibia self-drive for independent spirits; group departures for sociable value.</p>" @(@{"q"="Is solo safari safe?";"a"="Yes on standard circuits: pre-booked transfers, vetted camps, guides present all day. Cities need normal big-city sense - we brief every arrival."},@{"q"="Can supplements be avoided?";"a"="Sometimes: willing-to-share matching on group departures, green-season offers, and camps with no-supplement rooms. Ask per trip - policies vary."},@{"q"="Group or private for solos?";"a"="Groups for company and cost; private for photography and pace. Many solos mix: group safari plus private extension days."}) $REL
New-Guide "luxury-safari-guide" "Luxury Safari, Defined: What Money Actually Buys" "Luxury safari tiers explained: concessions, flying, suites, staff ratios - and what is just thread count." "Luxury changes sightings, not just sheets. Spend where privilege alters wildlife access; save where it only alters thread counts." "<h2>What luxury buys</h2><p>Private-concession traversing (off-road, night drives, walks), Migration-zone camp positioning, flying over driving, 1-to-4 staff ratios, suites with space and plunge pools.</p><h2>Tiers and prices</h2><p>Mid-luxury fly-in circuits: 800 to 1,100 dollars per day. Top-tier concessions and suites: 1,200 to 1,800 plus. Ultra-luxury (private vehicles, helicopters, exclusive-use camps): by quote.</p><h2>Where luxury matters most</h2><p>Botswana (low-volume policy makes it structural), Sabi Sand and Mara conservancies (traversing rights), Migration season (positioning). Least critical: Namibia self-drive routes and Cape Town city legs.</p>" @(@{"q"="Is luxury worth it in Botswana?";"a"="Botswana is mid-luxury by default due to fly-in logistics; true ultra-luxury buys iconic water camps and private traversing."},@{"q"="Can luxury and kids mix?";"a"="Yes - many luxury lodges run superb cubs programs with private activities and family suites. Ask for family-suite inventory early."},@{"q"="What is the smartest luxury splurge?";"a"="One private-concession stay for night drives and off-road sightings, plus one internal flight replacing the longest drive. Targeted, not blanket."}) $REL
"guides done"
